mapper.select:
select id, project_id, user_account_id, leader_account_id, status, disabled_at, created_at
from chat_sessions
where id = #{id}

mapper.update:
update chat_sessions
set leader_account_id = #{leaderAccountId}
where project_id = #{projectId}

mapper.select:
select count(*)
from chat_group_members
where group_id = #{sessionId}
  and account_id = #{accountId}
  and member_status = 'JOINED'

select member_role
from chat_group_members
where group_id = #{sessionId}
  and account_id = #{accountId}
limit 1

mapper.update:
update chat_group_members
set member_status = 'LEFT'
where group_id = #{sessionId}
  and account_id = #{accountId}
  and member_role = 'PARTICIPANT'
  and member_status = 'JOINED'
